  },
  "evidence_hash": {
   "$ref": "common.schema.json#/$defs/bytes32_hex"
  },
  "amount": {
   "$ref": "common.schema.json#/$defs/token_amount"
  },
  "tx_hash": {
   "$ref": "common.schema.json#/$defs/tx_hash"
  },
  "reason_code": {
   "$ref": "common.schema.json#/$defs/rejection_reason_code"
  },
